  if (iter != loadedArches.end()) {
    return (*iter).second;
  }
  ArchitectureCapability *xmlCapability = ArchitectureCapability::getCapability("xml");
  istringstream s(
      "<binaryimage arch=\"" + arch + "\"></binaryimage>"
  );
