  parse_protopieces(pieces,s,model->getArch());
  vector<ParameterPieces> res;
  model->assignParameterStorage(pieces, res, false);
  vector<VarnodeData> storeData;
  parseStores(model,storeData,stores);
  if (storeData.size() != res.size())
    return false;
