      if (iter == bb->beginOp()) {
	opDestroy(op);		// Get rid of the INDIRECT
	break;
      }
      else {
	--iter;
	opDestroy(op);
      }
    }
    else if (iter == bb->beginOp())
      break;
    else
      --iter;
  }

